import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Abstract Atom provider that safely reads Atom elements from an {@link InputStream}.
 *
 * <p>This implementation mitigates XXE risks by configuring the parser to disable
 * entity resolution before parsing. It also ensures that the parser options are
 * applied atomically and consistently across all threads.</p>
 */
public abstract class AbstractAtomProvider<T extends Element> implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Singleton Abdera instance used for parsing. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Flag indicating whether charset autodetection should be enabled. */
    private boolean autodetectCharset;

    /**
     * Reads an Atom element from the supplied {@link InputStream}.
     *
     * @param clazz   the expected type of the returned element
     * @param t       the generic type information
     * @param a       annotations present on the resource method
     * @param mt      media type of the request
     * @param headers HTTP headers of the request
     * @param is      input stream containing the Atom XML
     * @return the parsed Atom element
     * @throws IOException if an I/O error occurs while reading the stream
     */
    @Override
    public T readFrom(Class<T> clazz, Type t, Annotation[] a, MediaType mt,
                      MultivaluedMap<String, String> headers, InputStream is) throws IOException {

        // Obtain a fresh parser instance for each call to avoid shared state issues.
        Parser parser = ATOM_ENGINE.getParser();

        // Configure parser options to disable entity resolution and set charset autodetection.
        ParserOptions options = parser.getDefaultParserOptions();
        if (options == null) {
            throw new IllegalStateException("ParserOptions cannot be null");
        }
        options.setResolveEntities(false);          // Prevent XXE
        options.setAutodetectCharset(autodetectCharset);

        // Parse the input stream with the secured options.
        Document<T> doc = parser.parse(is, options);
        return doc.getRoot();
    }

    // Other methods omitted for brevity
}
