import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    static public File allocateFile(File dir, String name) {
        // Remove query parameters if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Normalize the target directory path
        Path normalizedDir = dir.toPath().normalize();

        // Resolve the requested file name against the directory
        Path resolvedPath = normalizedDir.resolve(name).normalize();

        // Ensure the resolved path stays within the intended directory
        if (!resolvedPath.startsWith(normalizedDir)) {
            throw new IllegalArgumentException(
                "Invalid file name: '" + name + "' escapes the target directory."
            );
        }

        // Construct the File object from the safe path
        File file = resolvedPath.toFile();

        // Determine prefix and suffix for duplicate handling
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            // Append a numeric suffix to avoid collisions
            String newName = prefix + "-" + index++ + suffix;
            Path newResolvedPath = normalizedDir.resolve(newName).normalize();

            // Double-check that the new name also stays within the directory
            if (!newResolvedPath.startsWith(normalizedDir)) {
                throw new IllegalArgumentException(
                    "Generated file name '" + newName + "' escapes the target directory."
                );
            }

            file = newResolvedPath.toFile();
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            boolean dirsCreated = parent.mkdirs();
            if (!dirsCreated && !parent.isDirectory()) {
                throw new IllegalStateException(
                    "Failed to create directories for: " + parent.getAbsolutePath()
                );
            }
        }

        return file;
    }

    // other methods

}
