import java.security.SecureRandom;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;
import org.springframework.util.FileCopyUtils;

public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private String algorithm = "SHA1PRNG";
    private Resource seed;

    // other methods

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = SecureRandom.getInstance(algorithm);
        if (seed != null) {
            // Read seed bytes but do NOT set them directly on SecureRandom.
            // Instead, generate a new SecureRandom instance seeded with the
            // provided seed, then discard it after extracting a single random
            // value. This ensures that the main SecureRandom instance remains
            // unpredictable and not influenced by external seed data.
            byte[] seedBytes = FileCopyUtils.copyToByteArray(seed.getInputStream());
            SecureRandom tempRnd = SecureRandom.getInstance(algorithm);
            tempRnd.setSeed(seedBytes);
            // Consume one random value to mix the seed into the internal state.
            tempRnd.nextBytes(new byte[1]);
            // Discard tempRnd; rnd remains unseeded by external data.
        } else {
            // Ensure rnd is seeded by its default mechanism.
            rnd.nextBytes(new byte[1]);
        }
        return rnd;
    }

    // other methods

}
