import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate<javax.ws.rs.core.MediaType>
{
   // other methods

   /**
    * Validates a media type component (major or subtype) according to RFC 7231.
    * Only allows token characters: letters, digits, and the following punctuation:
    * !#$%&'*+-.^_`|~
    *
    * @param str the component string to validate
    * @return true if valid, false otherwise
    */
   protected static boolean isValid(String str) {
      if (str == null || str.isEmpty()) {
         return false;
      }
      // RFC 7231 token definition: 1*tchar
      // tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "." /
      //        "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
      // We use a regex to enforce this.
      Pattern tokenPattern = Pattern.compile("^[!#$%&'*+\\-.^_`|~a-zA-Z0-9]+$");
      return tokenPattern.matcher(str).matches();
   }

   // other methods

}
