        int maxIterations = Integer.MAX_VALUE / vt;
        int iterations = 0;

        while (v < vt && iterations < maxIterations) {
            v += vt;
            iterations++;
        }

        // Final safety check: if we reached the maximum iterations, throw an exception
        if (iterations == maxIterations && v < vt) {
